//! Checkpoint 4, technique tests: is the library correct for the right
//! reasons?
//!
//! Run: cargo test --test technique
//!
//! These tests look at how the code works: how much memory it needs, when
//! it stops reading, whether threads really run at the same time, whether a
//! waiting thread sleeps, and whether a wake-up can get lost. All of them
//! must pass, in debug and with `--release`, for the "proficient" level in
//! RUBRIC.md. Do not edit this file.

mod common;

use std::fmt::{self, Write as _};
use std::future::Future;
use std::io::{self, BufRead, Cursor, ErrorKind, Read, Write};
use std::pin::{Pin, pin};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::{Arc, Barrier, Condvar, Mutex, mpsc};
use std::task::{Context, Poll, RawWaker, RawWakerVTable, Wake, Waker};
use std::thread;
use std::time::{Duration, Instant};

use common::{measure, within};
use seal::{
    Entry, EntryError, ManifestError, Status, block_on, check_all, digest, digest_all,
    in_background, read_manifest, write_manifest,
};

// ---------------------------------------------------------------- helpers

fn entry(digest: u64, name: &str) -> Entry {
    Entry {
        digest,
        name: name.to_string(),
    }
}

/// A waker that counts how often it was used.
#[derive(Default)]
struct Bell {
    rings: AtomicUsize,
}

impl Wake for Bell {
    fn wake(self: Arc<Self>) {
        self.rings.fetch_add(1, Ordering::SeqCst);
    }
}

fn bell() -> (Arc<Bell>, Waker) {
    let bell = Arc::new(Bell::default());
    (Arc::clone(&bell), Waker::from(bell))
}

/// Waits until `condition` holds. This is test code: the library itself
/// must not wait like this.
#[track_caller]
fn eventually(what: &str, condition: impl Fn() -> bool) {
    let start = Instant::now();
    while !condition() {
        assert!(
            start.elapsed() < Duration::from_secs(10),
            "{what} did not happen within 10 s"
        );
        thread::sleep(Duration::from_millis(1));
    }
}

// ------------------------------------------------------------------ bytes

/// Gives `left` zero bytes, as many per call as the buffer holds, and
/// counts the calls.
struct Zeros {
    left: usize,
    calls: usize,
}

impl Read for Zeros {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        self.calls += 1;
        let count = buf.len().min(self.left);
        buf[..count].fill(0);
        self.left -= count;
        Ok(count)
    }
}

#[test]
fn digest_needs_a_fixed_amount_of_memory() {
    let mut zeros = Zeros {
        left: 8 << 20,
        calls: 0,
    };
    let (result, heap) = measure(|| digest(&mut zeros));
    assert_eq!(result.unwrap(), 0x637a_2df5_4e22_2325);
    assert!(
        heap.bytes <= 64 * 1024,
        "digest of 8 MiB requested {} bytes of heap memory; the budget is 64 KiB. Read a \
         piece into a fixed buffer, add it to the hash, and use the same buffer again. Do \
         not collect the input first.",
        heap.bytes
    );
}

#[test]
fn digest_reads_large_pieces() {
    let mut zeros = Zeros {
        left: 1 << 20,
        calls: 0,
    };
    digest(&mut zeros).unwrap();
    assert!(
        zeros.calls <= 300,
        "digest called `read` {} times for 1 MiB; the budget is 300. Each call on a file is \
         a request to the operating system, so ask for some kilobytes at a time.",
        zeros.calls
    );
}

// ------------------------------------------------------------------- text

/// A place to format into that never allocates.
struct Fixed {
    bytes: [u8; 256],
    len: usize,
}

impl fmt::Write for Fixed {
    fn write_str(&mut self, text: &str) -> fmt::Result {
        let end = self.len + text.len();
        self.bytes
            .get_mut(self.len..end)
            .ok_or(fmt::Error)?
            .copy_from_slice(text.as_bytes());
        self.len = end;
        Ok(())
    }
}

#[test]
fn display_does_not_allocate() {
    let entries = [
        entry(0xaf63_dc4c_8601_ec8c, "notes/a.txt"),
        entry(255, "a\\b\\c\nd\re\\"),
        entry(u64::MAX, "\n\n\n\n\\\\\\\\ Zoë \r\r\r\r"),
    ];
    let expected = [
        "af63dc4c8601ec8c  notes/a.txt",
        "00000000000000ff  a\\\\b\\\\c\\nd\\re\\\\",
        "ffffffffffffffff  \\n\\n\\n\\n\\\\\\\\\\\\\\\\ Zoë \\r\\r\\r\\r",
    ];
    for (entry, expected) in entries.iter().zip(expected) {
        let mut out = Fixed {
            bytes: [0; 256],
            len: 0,
        };
        let (result, heap) = measure(|| write!(out, "{entry}"));
        assert_eq!(result, Ok(()));
        assert_eq!(std::str::from_utf8(&out.bytes[..out.len]), Ok(expected));
        assert_eq!(
            heap.calls, 0,
            "formatting {:?} allocated {} time(s). Write the pieces of the name to the \
             formatter one after the other; do not build an escaped String first.",
            entry.name, heap.calls
        );
    }
}

#[test]
fn parse_allocates_only_the_name() {
    for line in [
        "af63dc4c8601ec8c  notes/a.txt",
        "00000000000000ff  a\\\\b\\\\c\\nd\\re\\\\ and a long tail so that the name needs room",
    ] {
        let (result, heap) = measure(|| line.parse::<Entry>());
        assert!(result.is_ok());
        assert!(
            heap.calls <= 1,
            "parsing {line:?} allocated {} times; the budget is 1, for the name. The name is \
             never longer than its escaped form, so its capacity is known before the first \
             character is pushed. Do not build one String per replacement.",
            heap.calls
        );
        assert!(
            heap.bytes <= line.len(),
            "parsing {line:?} requested {} bytes for a line of {} bytes",
            heap.bytes,
            line.len()
        );
    }
    for (line, error) in [
        ("", EntryError::Digest),
        (
            "zzzzzzzzzzzzzzzz  a long name that is never looked at",
            EntryError::Digest,
        ),
        (
            "00000000000000ff a long name that is never looked at",
            EntryError::Separator,
        ),
        ("00000000000000ff  ", EntryError::Name),
    ] {
        let (result, heap) = measure(|| line.parse::<Entry>());
        assert_eq!(result, Err(error));
        assert_eq!(
            heap.calls, 0,
            "{line:?} is rejected before the name is read, so nothing needs to be allocated"
        );
    }
}

/// Counts bytes and throws them away.
struct Count(usize);

impl Write for Count {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        self.0 += buf.len();
        Ok(buf.len())
    }

    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

#[test]
fn write_manifest_does_not_allocate() {
    let entries: Vec<Entry> = (0..200)
        .map(|i| entry(i, &format!("dir {i}\\file\nwith a second line")))
        .collect();
    let mut out = Count(0);
    let (result, heap) = measure(|| write_manifest(&mut out, &entries));
    result.unwrap();
    let expected: usize = entries
        .iter()
        .map(|entry| entry.to_string().len() + 1)
        .sum();
    assert_eq!(out.0, expected);
    assert_eq!(
        heap.calls, 0,
        "writing 200 entries allocated {} time(s). Format straight into the writer; do not \
         build a String per line or one String for the whole manifest.",
        heap.calls
    );
}

/// A buffered reader that hands out one prepared piece per `fill_buf`, and
/// fails when it is asked for more pieces than `allowed`.
struct Pieces {
    pieces: Vec<&'static [u8]>,
    next: usize,
    current: &'static [u8],
    allowed: usize,
}

impl Pieces {
    fn new(pieces: &[&'static [u8]], allowed: usize) -> Pieces {
        Pieces {
            pieces: pieces.to_vec(),
            next: 0,
            current: b"",
            allowed,
        }
    }
}

impl Read for Pieces {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        let available = self.fill_buf()?;
        let count = available.len().min(buf.len());
        buf[..count].copy_from_slice(&available[..count]);
        self.consume(count);
        Ok(count)
    }
}

impl BufRead for Pieces {
    fn fill_buf(&mut self) -> io::Result<&[u8]> {
        if self.current.is_empty() {
            if self.next == self.allowed {
                return Err(io::Error::new(
                    ErrorKind::BrokenPipe,
                    "the reader was asked for input that lies after the failure",
                ));
            }
            self.current = self.pieces.get(self.next).copied().unwrap_or(b"");
            self.next += 1;
        }
        Ok(self.current)
    }

    fn consume(&mut self, amount: usize) {
        self.current = &self.current[amount..];
    }
}

#[test]
fn read_manifest_stops_at_the_first_failure() {
    let pieces: [&'static [u8]; 4] = [
        b"0000000000000001  one\n",
        b"0000000000000002  two\n",
        b"this line is not an entry\n",
        b"0000000000000004  four\n",
    ];
    // Three pieces may be fetched. Asking for the fourth is an I/O error.
    let result = read_manifest(Pieces::new(&pieces, 3));
    assert!(
        matches!(
            result,
            Err(ManifestError::Line {
                number: 3,
                error: EntryError::Digest
            })
        ),
        "line 3 is not an entry, and the reading must stop there. Reading the whole input \
         before the first line is parsed finds a later problem first. Got: {result:?}"
    );

    // The other way round: the I/O error comes before the bad line is seen.
    let result = read_manifest(Pieces::new(&pieces, 2));
    assert!(
        matches!(&result, Err(ManifestError::Io(error)) if error.kind() == ErrorKind::BrokenPipe),
        "{result:?}"
    );

    // A line that arrives in two pieces is still one line.
    let split: [&'static [u8]; 3] = [b"00000000000000", b"0a  split", b" name\n"];
    assert_eq!(
        read_manifest(Pieces::new(&split, 4)).unwrap(),
        [entry(10, "split name")]
    );
}

// ---------------------------------------------------------------- threads

/// A reader that waits at a barrier before its first byte. It gets through
/// only when as many readers as the barrier asks for wait at the same time.
struct Meet<'a> {
    barrier: &'a Barrier,
    waited: bool,
    data: Cursor<Vec<u8>>,
}

impl Read for Meet<'_> {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if !self.waited {
            self.waited = true;
            self.barrier.wait();
        }
        self.data.read(buf)
    }
}

#[test]
fn check_all_reads_with_all_workers_at_the_same_time() {
    for workers in [2, 4] {
        let statuses = within(
            20,
            "check_all with readers that wait for each other. The readers get through \
             only if `workers` of them are being read at the same time, so check_all",
            move || {
                let entries: Vec<Entry> = (0..workers * 3)
                    .map(|i| entry(0, &format!("f{i}")))
                    .collect();
                let barrier = Barrier::new(workers);
                check_all(&entries, workers, |name| {
                    Ok(Meet {
                        barrier: &barrier,
                        waited: false,
                        data: Cursor::new(name.as_bytes().to_vec()),
                    })
                })
            },
        );
        assert_eq!(statuses.len(), workers * 3, "one status for each entry");
        assert!(
            statuses
                .iter()
                .all(|status| matches!(status, Status::Changed(_)))
        );
    }
}

/// A reader that counts how many of its kind are alive.
struct Counted<'a> {
    alive: &'a AtomicUsize,
    data: Cursor<Vec<u8>>,
    slept: bool,
}

impl Read for Counted<'_> {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if !self.slept {
            self.slept = true;
            thread::sleep(Duration::from_millis(2));
        }
        self.data.read(buf)
    }
}

impl Drop for Counted<'_> {
    fn drop(&mut self) {
        self.alive.fetch_sub(1, Ordering::SeqCst);
    }
}

#[test]
fn check_all_never_has_more_readers_than_workers() {
    for workers in [1, 3] {
        let (peak, count) = within(20, "check_all", move || {
            let entries: Vec<Entry> = (0..40).map(|i| entry(0, &format!("f{i}"))).collect();
            let alive = AtomicUsize::new(0);
            let peak = AtomicUsize::new(0);
            let statuses = check_all(&entries, workers, |name| {
                let now = alive.fetch_add(1, Ordering::SeqCst) + 1;
                peak.fetch_max(now, Ordering::SeqCst);
                Ok(Counted {
                    alive: &alive,
                    data: Cursor::new(name.as_bytes().to_vec()),
                    slept: false,
                })
            });
            assert_eq!(
                alive.load(Ordering::SeqCst),
                0,
                "every reader must be dropped before check_all returns"
            );
            (peak.load(Ordering::SeqCst), statuses.len())
        });
        assert_eq!(count, 40, "one status for each of the 40 entries");
        assert!(
            peak <= workers,
            "with workers = {workers}, {peak} readers were alive at the same time. One thread \
             per entry is not what `workers` means; and a reader must be dropped before its \
             thread opens the next one."
        );
    }
}

#[test]
fn check_all_a_slow_file_does_not_keep_the_others_waiting() {
    let statuses = within(
        20,
        "check_all with one slow file. The slow reader waits until every other entry has \
         been opened, so entries must not be tied to the worker that is stuck. check_all",
        || {
            let names = ["slow", "b", "c", "d", "e", "f", "g"];
            let entries: Vec<Entry> = names.iter().map(|name| entry(0, name)).collect();
            let opened = Mutex::new(0usize);
            let all_opened = Condvar::new();

            struct Slow<'a> {
                gate: Option<(&'a Mutex<usize>, &'a Condvar, usize)>,
                data: Cursor<Vec<u8>>,
            }
            impl Read for Slow<'_> {
                fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
                    if let Some((opened, all_opened, total)) = self.gate.take() {
                        let mut count = opened.lock().unwrap();
                        while *count < total {
                            count = all_opened.wait(count).unwrap();
                        }
                    }
                    self.data.read(buf)
                }
            }

            check_all(&entries, 2, |name| {
                *opened.lock().unwrap() += 1;
                all_opened.notify_all();
                let gate = (name == "slow").then_some((&opened, &all_opened, names.len()));
                Ok(Slow {
                    gate,
                    data: Cursor::new(name.as_bytes().to_vec()),
                })
            })
        },
    );
    assert_eq!(statuses.len(), 7, "one status for each of the 7 entries");
}

// --------------------------------------------------------------- block_on

/// Completes at the poll after another thread has used the waker. Counts
/// its polls.
struct Later {
    done: Arc<AtomicBool>,
    polls: Arc<AtomicUsize>,
    started: bool,
    wait: Duration,
}

impl Future for Later {
    type Output = ();

    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        self.polls.fetch_add(1, Ordering::SeqCst);
        if self.done.load(Ordering::SeqCst) {
            return Poll::Ready(());
        }
        if !self.started {
            self.started = true;
            let (done, wait, waker) = (Arc::clone(&self.done), self.wait, cx.waker().clone());
            thread::spawn(move || {
                thread::sleep(wait);
                done.store(true, Ordering::SeqCst);
                waker.wake();
            });
        }
        Poll::Pending
    }
}

#[test]
fn block_on_sleeps_between_polls() {
    let polls = within(20, "block_on", || {
        let polls = Arc::new(AtomicUsize::new(0));
        block_on(Later {
            done: Arc::new(AtomicBool::new(false)),
            polls: Arc::clone(&polls),
            started: false,
            wait: Duration::from_millis(100),
        });
        polls.load(Ordering::SeqCst)
    });
    assert!(
        polls <= 10,
        "block_on polled a future {polls} times while it waited 100 ms for one wake-up; two \
         polls are enough. After a poll returns Pending, the thread must sleep until the \
         waker is used, not poll again in a loop."
    );
}

/// Asks to be polled again from inside `poll`, a number of times.
struct Again(u32);

impl Future for Again {
    type Output = ();

    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        if self.0 == 0 {
            return Poll::Ready(());
        }
        self.0 -= 1;
        cx.waker().wake_by_ref();
        Poll::Pending
    }
}

/// Has its waker used by another thread, and waits until that has happened,
/// before `poll` returns `Pending`.
struct WokenEarly(u32);

impl Future for WokenEarly {
    type Output = ();

    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        if self.0 == 0 {
            return Poll::Ready(());
        }
        self.0 -= 1;
        let waker = cx.waker().clone();
        thread::spawn(move || waker.wake()).join().unwrap();
        Poll::Pending
    }
}

#[test]
fn block_on_does_not_lose_a_wake_that_comes_before_it_sleeps() {
    within(
        30,
        "block_on with a waker that is used before `poll` returns. The wake-up comes before \
         the thread has started to sleep and must be remembered, so block_on",
        || {
            block_on(Again(20_000));
            block_on(WokenEarly(300));
            block_on(async {
                for _ in 0..100 {
                    Again(1).await;
                    WokenEarly(1).await;
                }
            });
        },
    );
}

// ------------------------------------------------------------- background

#[test]
fn background_poll_does_not_wait_for_the_work() {
    within(
        20,
        "polling a Background whose work is not finished. `poll` must return Pending at \
         once and must not wait for the thread, so the poll",
        || {
            let (release, gate) = mpsc::channel::<()>();
            let mut job = pin!(in_background(move || gate.recv().is_ok()));
            let (_, waker) = bell();
            let mut context = Context::from_waker(&waker);
            assert!(job.as_mut().poll(&mut context).is_pending());
            assert!(job.as_mut().poll(&mut context).is_pending());
            release.send(()).unwrap();
        },
    );
}

#[test]
fn background_wakes_the_most_recent_waker() {
    within(20, "the test of Background's waker", || {
        let (release, gate) = mpsc::channel::<()>();
        let mut job = pin!(in_background(move || {
            let _ = gate.recv();
            5
        }));
        let (first, first_waker) = bell();
        let (second, second_waker) = bell();
        assert!(
            job.as_mut()
                .poll(&mut Context::from_waker(&first_waker))
                .is_pending()
        );
        assert!(
            job.as_mut()
                .poll(&mut Context::from_waker(&second_waker))
                .is_pending()
        );
        assert_eq!(
            first.rings.load(Ordering::SeqCst) + second.rings.load(Ordering::SeqCst),
            0,
            "no waker may be used before the work has ended"
        );

        release.send(()).unwrap();
        eventually(
            "the use of the waker of the second poll (a future must wake the waker of its \
             most recent poll, because the first one may belong to a task that has given \
             the future away)",
            || second.rings.load(Ordering::SeqCst) > 0,
        );
        assert_eq!(
            job.as_mut().poll(&mut Context::from_waker(&second_waker)),
            Poll::Ready(Ok(5)),
            "when the waker has been used, the result must be there"
        );
    });
}

#[test]
fn background_gives_a_finished_result_at_the_next_poll() {
    within(20, "the test of Background's waker", || {
        // The work is over, or as good as over, when the future is polled
        // for the first time. Polling must then return the result soon, and
        // the waker is used at most once.
        let (done, finished) = mpsc::channel::<()>();
        let mut job = pin!(in_background(move || {
            drop(done);
            "early"
        }));
        let _ = finished.recv();
        let (rings, waker) = bell();
        let mut context = Context::from_waker(&waker);
        let start = Instant::now();
        let result = loop {
            if let Poll::Ready(result) = job.as_mut().poll(&mut context) {
                break result;
            }
            assert!(
                start.elapsed() < Duration::from_secs(10),
                "the work has ended, but polling does not return its result"
            );
            thread::sleep(Duration::from_millis(1));
        };
        assert_eq!(result, Ok("early"));
        assert!(
            rings.rings.load(Ordering::SeqCst) <= 1,
            "the work ends once, so a waker is used at most once"
        );
    });
}

#[test]
fn background_never_loses_a_wake_up() {
    within(
        60,
        "1500 times block_on(in_background(..)). If this hangs, the work can end between \
         the moment `poll` looks for the result and the moment it stores the waker, and \
         then nobody is woken. The loop",
        || {
            for round in 0..1500u32 {
                let job = in_background(move || {
                    // Sometimes the work ends before the first poll,
                    // sometimes during it, sometimes after it.
                    for _ in 0..round % 7 {
                        thread::yield_now();
                    }
                    round
                });
                assert_eq!(block_on(job), Ok(round));
            }
        },
    );
}

/// The state behind a waker whose `clone` takes its time. The first `clone`
/// lets the background work go and then waits, so that the work ends while
/// the future is in the middle of `poll`.
struct Slow {
    rings: AtomicUsize,
    release: Mutex<Option<mpsc::Sender<()>>>,
}

static SLOW_VTABLE: RawWakerVTable =
    RawWakerVTable::new(slow_clone, slow_wake, slow_wake_by_ref, slow_drop);

// The four functions below are the hand-written form of what
// `Waker::from(Arc<impl Wake>)` generates, plus the pause in `clone`. The
// data pointer of every such waker comes from `Arc::<Slow>::into_raw`, and
// each waker owns one strong count.

unsafe fn slow_clone(data: *const ()) -> RawWaker {
    // SAFETY: `data` comes from `Arc::<Slow>::into_raw`, and the waker that
    // is being cloned keeps the `Slow` alive during this call.
    let slow = unsafe { &*data.cast::<Slow>() };
    if let Some(release) = slow.release.lock().unwrap().take() {
        let _ = release.send(());
        thread::sleep(Duration::from_millis(60));
    }
    // SAFETY: as above; the new waker gets a strong count of its own.
    unsafe { Arc::increment_strong_count(data.cast::<Slow>()) };
    RawWaker::new(data, &SLOW_VTABLE)
}

unsafe fn slow_wake(data: *const ()) {
    // SAFETY: `wake` consumes the waker, and with it its strong count.
    let slow = unsafe { Arc::from_raw(data.cast::<Slow>()) };
    slow.rings.fetch_add(1, Ordering::SeqCst);
}

unsafe fn slow_wake_by_ref(data: *const ()) {
    // SAFETY: the waker is borrowed for this call and keeps `Slow` alive.
    let slow = unsafe { &*data.cast::<Slow>() };
    slow.rings.fetch_add(1, Ordering::SeqCst);
}

unsafe fn slow_drop(data: *const ()) {
    // SAFETY: dropping a waker gives its strong count back.
    drop(unsafe { Arc::from_raw(data.cast::<Slow>()) });
}

fn slow_waker(release: mpsc::Sender<()>) -> (Arc<Slow>, Waker) {
    let slow = Arc::new(Slow {
        rings: AtomicUsize::new(0),
        release: Mutex::new(Some(release)),
    });
    let data = Arc::into_raw(Arc::clone(&slow)).cast::<()>();
    // SAFETY: the vtable functions treat `data` as the `Arc<Slow>` it is,
    // keep the strong counts balanced, and `Slow` is `Send + Sync`.
    let waker = unsafe { Waker::from_raw(RawWaker::new(data, &SLOW_VTABLE)) };
    (slow, waker)
}

#[test]
fn background_keeps_a_result_that_arrives_during_poll() {
    within(
        20,
        "the test of a result that arrives during `poll`",
        || {
            let (release, gate) = mpsc::channel::<()>();
            let mut job = pin!(in_background(move || {
                let _ = gate.recv();
                11
            }));
            // When `poll` copies this waker, the copy releases the work and
            // then takes 60 ms. So the work ends after `poll` has started and
            // before `poll` has stored the waker.
            let (slow, waker) = slow_waker(release);
            let mut context = Context::from_waker(&waker);
            if job.as_mut().poll(&mut context) == Poll::Ready(Ok(11)) {
                return; // The poll saw the result itself. That is one correct answer.
            }
            eventually(
                "the use of the waker. The work ended while `poll` was copying the waker. That \
             poll returned Pending, so the waker it stored must be used. If `poll` looks \
             for the result, lets go of the lock and stores the waker afterwards, the work \
             can end in between, and then nobody is woken. The wake-up",
                || slow.rings.load(Ordering::SeqCst) > 0,
            );
            assert_eq!(job.as_mut().poll(&mut context), Poll::Ready(Ok(11)));
        },
    );
}

/// Tells the test when it is dropped.
struct Noisy(mpsc::Sender<&'static str>);

impl Drop for Noisy {
    fn drop(&mut self) {
        let _ = self.0.send("result dropped");
    }
}

#[test]
fn background_work_goes_on_when_the_future_is_dropped() {
    within(30, "the test of a dropped Background", || {
        for poll_first in [false, true] {
            let (events, seen) = mpsc::channel();
            let (release, gate) = mpsc::channel::<()>();
            let job = in_background(move || {
                let _ = gate.recv();
                let _ = events.send("work finished");
                Noisy(events)
            });
            let (rings, waker) = bell();
            if poll_first {
                let mut job = pin!(job);
                assert!(
                    job.as_mut()
                        .poll(&mut Context::from_waker(&waker))
                        .is_pending()
                );
                // The pinned future is dropped at the end of this block.
            } else {
                // The future is dropped at the end of this block, unpolled.
                let _unpolled = job;
            }
            release.send(()).unwrap();
            let wait = Duration::from_secs(10);
            assert_eq!(
                seen.recv_timeout(wait),
                Ok("work finished"),
                "dropping the future must not stop the work"
            );
            assert_eq!(
                seen.recv_timeout(wait),
                Ok("result dropped"),
                "the result of work that nobody waits for must be dropped, not kept for ever"
            );
            assert!(
                rings.rings.load(Ordering::SeqCst) <= 1,
                "the work ends once, so a waker is used at most once"
            );
        }
    });
}

// ------------------------------------------------------------- digest_all

/// Like `Meet`, but it owns what it needs, so it can move to a thread.
struct MeetOwned {
    barrier: Arc<Barrier>,
    waited: bool,
    data: Cursor<Vec<u8>>,
}

impl Read for MeetOwned {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if !self.waited {
            self.waited = true;
            self.barrier.wait();
        }
        self.data.read(buf)
    }
}

#[test]
fn digest_all_reads_all_readers_at_the_same_time() {
    let digests = within(
        20,
        "digest_all with readers that wait for each other. They get through only if all of \
         them are being read at the same time: start every background job before you await \
         the first one. digest_all",
        || {
            let barrier = Arc::new(Barrier::new(6));
            let readers: Vec<MeetOwned> = (0..6u8)
                .map(|i| MeetOwned {
                    barrier: Arc::clone(&barrier),
                    waited: false,
                    data: Cursor::new(vec![i; 10]),
                })
                .collect();
            block_on(digest_all(readers))
        },
    );
    assert_eq!(digests.len(), 6, "one result for each of the 6 readers");
    assert!(digests.iter().all(|result| result.is_ok()));
}
